    def _propagate(self):
        # Collect every downstream compute cell.
        affected = set()
        stack = list(self._dependents)
        while stack:
            cell = stack.pop()
            if cell in affected:
                continue
            affected.add(cell)
            stack.extend(cell._dependents)

        # Recompute in topological order (depth guarantees inputs first).
        ordered = sorted(affected, key=lambda c: c.depth)
